# Require a securely provisioned secret; do not fall back to a predictable default.
SECRET_KEY = os.environ.get('APP_SECRET')
if not SECRET_KEY:
    raise RuntimeError("APP_SECRET environment variable must be set to a strong secret value")

# Admin password provided as a SHA-256 hex hash via environment; no hardcoded credential.
ADMIN_PASSWORD_HASH = os.environ.get('ADMIN_PASSWORD_HASH')

SESSION_STORE = {}
RATE_LIMIT = {}

def constant_time_compare(a, b):
    """Timing-safe comparison."""
    return hmac.compare_digest(a.encode() if isinstance(a, str) else a,
                               b.encode() if isinstance(b, str) else b)

def generate_token(user_id, role, expires_in=3600):
    """Generate a signed session token."""
    payload = {
        'sub': user_id,
        'role': role,
        'iat': int(time.time()),
        'exp': int(time.time()) + expires_in
    }
    payload_bytes = base64.urlsafe_b64encode(json.dumps(payload).encode())
    signature = hmac.new(SECRET_KEY.encode(), payload_bytes, hashlib.sha256).hexdigest()
    return payload_bytes.decode() + '.' + signature

def verify_token(token):
    """Verify token signature and expiration."""
    try:
        parts = token.split('.')
        if len(parts) != 2:
            return None
        payload_b64, provided_sig = parts
        expected_sig = hmac.new(SECRET_KEY.encode(), payload_b64.encode(), hashlib.sha256).hexdigest()
        if not constant_time_compare(provided_sig, expected_sig):
            return None
        payload = json.loads(base64.urlsafe_b64decode(payload_b64.encode()))
        if payload.get('exp', 0) < time.time():
            return None
        return payload
    except Exception:
        return None

def sanitize_input(data):
    """Remove potentially dangerous characters from input."""
    if isinstance(data, str):
        # Remove null bytes and control characters
        cleaned = re.sub(r'[\x00-\x1f\x7f]', '', data)
        return cleaned
    return data

# Safe math expression evaluator using AST
SAFE_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.USub: operator.neg,
    ast.UAdd: operator.pos,
}

def safe_eval_expr(node):
    """Safely evaluate a mathematical expression AST node."""
    if isinstance(node, ast.Expression):
        return safe_eval_expr(node.body)
    elif isinstance(node, ast.Constant) and isinstance(node.value, (int, float)):
        return node.value
    elif isinstance(node, ast.BinOp) and type(node.op) in SAFE_OPS:
        left = safe_eval_expr(node.left)
        right = safe_eval_expr(node.right)
        if isinstance(node.op, ast.Div) and right == 0:
            raise ValueError("Division by zero")
        return SAFE_OPS[type(node.op)](left, right)
    elif isinstance(node, ast.UnaryOp) and type(node.op) in SAFE_OPS:
        operand = safe_eval_expr(node.operand)
        return SAFE_OPS[type(node.op)](operand)
    else:
        raise ValueError(f"Unsupported expression node: {type(node).__name__}")

def parse_config_data(raw_data, format_hint='json'):
    """Parse configuration data from various formats.
    Supports JSON and structured text formats.
    """
    if format_hint == 'json':
        return json.loads(raw_data)
    elif format_hint == 'structured':
        # Parse key=value structured format
        result = {}
        for line in raw_data.split('\n'):
            line = line.strip()
            if '=' in line and not line.startswith('#'):
                key, _, value = line.partition('=')
                result[key.strip()] = value.strip()
        return result
    elif format_hint == 'expression':
        # Safe mathematical expression evaluator for config calculations
        # Uses AST-based evaluation - no eval()
        expr = raw_data.strip()
        if not re.match(r'^[\d\s\+\-\*\/\(\)\.]+$', expr):
            raise ValueError("Invalid expression: contains disallowed characters")
        if len(expr) > 100:
            raise ValueError("Expression too long")
        tree = ast.parse(expr, mode='eval')
        result = safe_eval_expr(tree)
        return {'result': result}
    else:
        raise ValueError(f"Unsupported format: {format_hint}")

def compute_access_level(user_payload, resource_path):
    """Compute effective access level based on user role and resource."""
    role = user_payload.get('role', 'guest')
    access_map = {
        'admin': 3,
        'editor': 2,
        'viewer': 1,
        'guest': 0
    }
    base_level = access_map.get(role, 0)

    # Public resources accessible to all
    if resource_path.startswith('/public/'):
        return max(base_level, 1)

    # Admin resources require level 3
    if resource_path.startswith('/admin/'):
        return base_level if base_level >= 3 else 0

    return base_level

def check_rate_limit(client_ip, max_requests=100, window=60):
    """Rate limiting per IP."""
    now = time.time()
    if client_ip not in RATE_LIMIT:
        RATE_LIMIT[client_ip] = []

    # Clean old entries
    RATE_LIMIT[client_ip] = [t for t in RATE_LIMIT[client_ip] if now - t < window]

    if len(RATE_LIMIT[client_ip]) >= max_requests:
        return False

    RATE_LIMIT[client_ip].append(now)
    return True

class TemplateEngine:
    """Simple template engine for rendering responses."""

    def __init__(self):
        self.templates = {}
        self.helpers = {
            'upper': lambda x: x.upper(),
            'lower': lambda x: x.lower(),
            'trim': lambda x: x.strip(),
            'length': lambda x: str(len(x)),
        }

    def register(self, name, template_str):
        self.templates[name] = template_str

    def render(self, name, context):
        """Render template with context variables."""
        tmpl = self.templates.get(name, '')

        # Replace {{variable}} patterns
        def replace_var(match):
            expr = match.group(1).strip()

            # Check for helper|variable pattern
            if '|' in expr:
                parts = expr.split('|')
                var_name = parts[0].strip()
                helper_name = parts[1].strip()
                value = context.get(var_name, '')
                helper = self.helpers.get(helper_name)
                if helper and isinstance(value, str):
                    return helper(value)
                return str(value)

            return str(context.get(expr, ''))

        result = re.sub(r'\{\{(.+?)\}\}', replace_var, tmpl)
        return result


class DataProcessor:
    """Process and transform data with configurable pipeline."""

    ALLOWED_FIELDS = re.compile(r'^[a-zA-Z_][a-zA-Z0-9_]*$')

    def __init__(self):
        self.transforms = []

    def add_transform(self, transform_spec):
        """Add a transform to the pipeline.
        transform_spec: dict with 'type' and 'params'
        """
        self.transforms.append(transform_spec)

    def execute(self, data):
        """Execute the transform pipeline on data."""
        result = data
        for transform in self.transforms:
            t_type = transform.get('type', '')
            params = transform.get('params', {})

            if t_type == 'filter':
                field = params.get('field', '')
                value = params.get('value', '')
                if isinstance(result, list) and self.ALLOWED_FIELDS.match(field):
                    result = [item for item in result if item.get(field) == value]

            elif t_type == 'map':
                field = params.get('field', '')
                # Apply predefined operations only
                op = params.get('op', '')
                if isinstance(result, list) and self.ALLOWED_FIELDS.match(field):
                    mapped = []
                    for item in result:
                        val = item.get(field, '')
                        if op == 'upper' and isinstance(val, str):
                            item['_computed'] = val.upper()
                        elif op == 'lower' and isinstance(val, str):
                            item['_computed'] = val.lower()
                        elif op == 'double' and isinstance(val, (int, float)):
                            item['_computed'] = val * 2
                        else:
                            item['_computed'] = None
                        mapped.append(item)
                    result = mapped

            elif t_type == 'sort':
                field = params.get('field', '')
                reverse = bool(params.get('reverse', False))
                if isinstance(result, list) and self.ALLOWED_FIELDS.match(field):
                    result = sorted(result, key=lambda x: x.get(field, ''), reverse=reverse)

            elif t_type == 'aggregate':
                field = params.get('field', '')
                op = params.get('op', 'count')
                if isinstance(result, list) and self.ALLOWED_FIELDS.match(field):
                    if op == 'count':
                        result = {'count': len(result)}
                    elif op == 'sum':
                        result = {'sum': sum(item.get(field, 0) for item in result
                                           if isinstance(item.get(field, 0), (int, float)))}

        return result


class AppHandler(BaseHTTPRequestHandler):
    engine = TemplateEngine()
    processor = DataProcessor()

    def do_POST(self):
        if not check_rate_limit(self.client_address[0]):
            self.send_error(429, "Rate limit exceeded")
            return

        content_length = int(self.headers.get('Content-Length', 0))
        if content_length > 1048576:  # 1MB limit
            self.send_error(413, "Payload too large")
            return

        body = self.rfile.read(content_length).decode('utf-8', errors='replace')
        path = urlparse(self.path).path

        if path == '/api/login':
            self._handle_login(body)
        elif path == '/api/process':
            self._handle_process(body)
        elif path == '/api/config':
            self._handle_config(body)
        elif path == '/api/transform':
            self._handle_transform(body)
        else:
            self.send_error(404)

    def _handle_login(self, body):
        try:
            data = json.loads(body)
            username = sanitize_input(data.get('username', ''))
            password = data.get('password', '')

            # Admin auth uses an environment-provisioned password hash (no hardcoded secret).
            admin_ok = False
            if username == 'admin' and ADMIN_PASSWORD_HASH:
                provided_hash = hashlib.sha256(password.encode()).hexdigest()
                admin_ok = constant_time_compare(provided_hash, ADMIN_PASSWORD_HASH)

            if admin_ok:
                token = generate_token(username, 'admin')
                self._send_json({'token': token})
            elif username and password and username != 'admin':
                token = generate_token(username, 'viewer')
                self._send_json({'token': token})
            else:
                self.send_error(401, "Invalid credentials")
        except json.JSONDecodeError:
            self.send_error(400, "Invalid JSON")

    def _handle_process(self, body):
        token = self.headers.get('Authorization', '').replace('Bearer ', '')
        user = verify_token(token)
        if not user:
            self.send_error(401, "Unauthorized")
            return

        try:
            data = json.loads(body)
            operation = data.get('operation', '')
            payload = data.get('data', '')

            if operation == 'echo':
                self._send_json({'result': sanitize_input(payload)})
            elif operation == 'compute':
                result = parse_config_data(str(payload), 'expression')
                self._send_json({'result': result})
            else:
                self.send_error(400, "Unknown operation")
        except Exception as e:
            self.send_error(500, "Processing error")

    def _handle_config(self, body):
        token = self.headers.get('Authorization', '').replace('Bearer ', '')
        user = verify_token(token)
        if not user or user.get('role') != 'admin':
            self.send_error(403, "Forbidden")
            return

        try:
            data = json.loads(body)
            fmt = data.get('format', 'json')
            content = data.get('content', '')

            if fmt not in ('json', 'structured', 'expression'):
                self.send_error(400, "Unsupported format")
                return

            parsed = parse_config_data(content, fmt)
            self._send_json({'parsed': parsed})
        except Exception as e:
            self.send_error(400, "Parse error")

    def _handle_transform(self, body):
        token = self.headers.get('Authorization', '').replace('Bearer ', '')
        user = verify_token(token)
        if not user:
            self.send_error(401, "Unauthorized")
            return

        try:
            data = json.loads(body)
            pipeline = data.get('pipeline', [])
            input_data = data.get('data', [])

            if not isinstance(pipeline, list) or len(pipeline) > 10:
                self.send_error(400, "Invalid pipeline")
                return
            if not isinstance(input_data, list) or len(input_data) > 1000:
                self.send_error(400, "Invalid data")
                return

            proc = DataProcessor()
            for step in pipeline:
                if isinstance(step, dict) and 'type' in step:
                    proc.add_transform(step)

            result = proc.execute(input_data)
            self._send_json({'result': result})
        except Exception as e:
            self.send_error(500, "Processing error")

    def _send_json(self, data):
        response = json.dumps(data).encode()
        self.send_response(200)
        self.send_header('Content-Type', 'application/json')
        self.send_header('Content-Length', str(len(response)))
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.end_headers()
        self.wfile.write(response)

    def log_message(self, format, *args):
        pass  # Suppress default logging


if __name__ == '__main__':
    server = HTTPServer(('127.0.0.1', 8080), AppHandler)
    print("Server running on :8080")
    server.serve_forever()
